def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    zeroish_count = 0
    desperate_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 150:
                    aggressive_count += 1
                if bid <= 1:
                    zeroish_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 40.0))
        return float(min(budget, 10.0))

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        base = 165.0 if tight_supply else 145.0
        if aggressive_count >= 2:
            base += 15.0
        return float(min(budget, base))

    if hp <= 4 or no_water >= 1:
        base = 95.0 if tight_supply else 72.0
        if aggressive_count >= 2:
            base = max(base, 110.0)
        elif prev_bids:
            observed = max(prev_bids)
            if observed < 120:
                base = max(base, observed + 3.0)
        return float(min(budget, base))

    if aggressive_count >= 2:
        if ample_supply and hp >= 7:
            return float(min(budget, 6.0))
        return float(min(budget, 14.0 if tight_supply else 9.0))

    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev <= 1:
            bid = 12.0 if tight_supply else 8.0
        elif highest_prev < 60:
            bid = highest_prev + 2.0
        elif highest_prev < 110:
            bid = 48.0 if ample_supply else 62.0
        else:
            bid = 18.0 if ample_supply else 28.0
    else:
        bid = 12.0 if tight_supply else 8.0

    if desperate_opp >= 2 and tight_supply:
        bid += 8.0

    if day >= 8 and hp >= 6 and no_water == 0:
        bid *= 0.8

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    bid_amount = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 4:
        bid_amount = DAILY_SALARY * 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                bid_amount = max(bid_amount, highest_prev_bid * 0.9)
            else:
                bid_amount = max(bid_amount, highest_prev_bid + 5)
        elif highest_prev_bid > DAILY_SALARY * 0.5:
            bid_amount = max(bid_amount, highest_prev_bid + 1)

    final_bid = min(my_status['budget'], bid_amount)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
